function IdolLive3D_UIIKHande:__init( uiMain_, rootTF_ )

    self.uiMain      = uiMain_
    self.rootTF      = rootTF_
    self.ImgHand     = rootTF_:Find("ImgHand")   -- 手
    self.ImgLight    = rootTF_:Find("ImgLight")  -- 光圈1
    self.ImgLight2   = rootTF_:Find("ImgLight2") -- 光圈2
    self.mCamera = IdolLive3D_Utils.GetMainCamera()
    self.isShow = false


    -- prefab 中, 原始 scale 是 2.0, 暂时改为 1.0:
    local newCircleScale = Vector3.one*2.0 * 0.5
    self.ImgLight.localScale  = newCircleScale
    self.ImgLight2.localScale = newCircleScale

    
    -- !!! 在 order 105 处调用 LateUpdate(), 以此规避掉由 CinemachineBrain 导致的 ui 元素晃动问题 
    self.LateUpdateFunc = function()
        self:SetUpdate()
    end
    self.behaviorExecutedAtOrder105 = KTool.GetOrAddComponent(self.rootTF.gameObject, typeof(BehaviorExecutedAtOrder105))
    self.behaviorExecutedAtOrder105:INTERNAL_LateUpdate( '+', self.LateUpdateFunc )


    self.rootCanvasCoordinateMatrix = DreamSpaceUtils.RefreshRootCanvasCoordinateMatrix( self.rootTF )

    self.ikUIHandMoveMode = IKUIHandMoveMode.PingPong

    self.cosPingPong = CosPingPong.New(1)
    self.singleDirMove = SingleDirectionMove.New(1)

    self.params = {
        initHandAnchoredPos = self.ImgHand.anchoredPosition,
        handAnchoredPos_1 = Vector2( -50, -50 ),
        handAnchoredPos_2 = Vector2(  50,  50 ),
        tgtTF = nil,
    }

    self:SetShow(false)
end


-- 需手动调用 Delete()
function IdolLive3D_UIIKHande:__delete()
    if isNotNull(self.cosPingPong) then 
        self.cosPingPong:Delete()
    end 
    if isNotNull(self.singleDirMove) then 
        self.singleDirMove:Delete()
    end 
    if isNotNull(self.circleArc) then 
        self.circleArc:Delete()
    end 

    self.behaviorExecutedAtOrder105:INTERNAL_LateUpdate( '-', self.LateUpdateFunc )
    self.LateUpdateFunc = nil
end


function IdolLive3D_UIIKHande:SetParmas( tgtTF_, ikUIHandMoveMode_, dirDegree_, swingLen_, handSwingCurvature_, movePeriod_ )
    self.params.tgtTF = tgtTF_
    ---
    local dir = IdolLive3D_Utils.Angle2Dir( dirDegree_, Vector3.up, Vector3.back )
    local halfLen = swingLen_ * 0.5 -- 像素
    self.params.handAnchoredPos_1 = Vector2( dir.x * halfLen, dir.y * halfLen )
    self.params.handAnchoredPos_2 = Vector2( -dir.x * halfLen, -dir.y * halfLen )


    self.circleArc = CircleArc.New()
    self.circleArc:SetParmas( dirDegree_, swingLen_, Vector3.back, handSwingCurvature_ )


    self.ikUIHandMoveMode = ikUIHandMoveMode_
    if self.ikUIHandMoveMode == IKUIHandMoveMode.PingPong then 
        self.cosPingPong:SetMovePeriod(movePeriod_)
    else 
        self.singleDirMove:SetMovePeriod(movePeriod_)
    end     
end


function IdolLive3D_UIIKHande:SetUpdate()
    if isNull(self.uiMain) or self.uiMain.isInit ~= true then 
        return
    end 

    -- if IdolLive3D_Utils.IsEditorPlatform() then
    --     if Input.GetKeyDown(KeyCode.J) then 
    --         self:SetParmas( nil, IKUIHandMoveMode.PingPong, 30, 300, 1.5 )
    --     end
    --     if Input.GetKeyDown(KeyCode.M) then 
    --         self:SetParmas( nil, IKUIHandMoveMode.PingPong, 100, 300, 1.5 )
    --     end
    -- end

    if self.isShow == false then 
        return
    end 

    if isNotNull(self.params.tgtTF) then 
        self:SetRootPos( self.params.tgtTF.position )
    end 

    
    local t = 0.0 -- [0.0,1.0]
    if self.ikUIHandMoveMode == IKUIHandMoveMode.PingPong then 
        t = self.cosPingPong:SetUpdate()
    else 
        --t = 1.0 - self.singleDirMove:SetUpdate() -- 翻转来符合 dir 参数的目的
        t = self.singleDirMove:SetUpdate()
    end 

    local tPos = self.circleArc:GetPos(t)
    self.ImgHand.anchoredPosition = self.params.initHandAnchoredPos + Vector2(tPos.x, tPos.y)

    --self.ImgHand.anchoredPosition = Vector2.Lerp( self.params.initHandAnchoredPos + self.params.handAnchoredPos_1, self.params.initHandAnchoredPos + self.params.handAnchoredPos_2, t )
end


----------------------------------------------------------


function IdolLive3D_UIIKHande:SetRootPos( posWS_ )
    -- Vector2
    local newAnchoredPosition = DreamSpaceUtils.CalculateAnchoredPosition( self.mCamera, posWS_, 0 )
    -- 准确计算 ui元素的 world-space 3d position:
    local pos = DreamSpaceUtils.AnchoredPosition_To_PosWS( newAnchoredPosition, self.rootCanvasCoordinateMatrix );
    self.rootTF.position = pos
end


function IdolLive3D_UIIKHande:SetShow( isShow_ )
    self.isShow = (isShow_==true)
    CfUtils.SetActive( self.rootTF, self.isShow  )
end







return IdolLive3D_UIIKHande
